use customer_behavior;
select * from customer;

-- 1. Revenue Analysis — Compared total revenue generated by male and female customers.

select gender, sum(purchase_amount) as total_revenue
from customer
group by gender;

-- 2. Discount & Spending Analysis — Identified discount users whose purchase amounts were at or above the overall average.

select * 
from customer
where discount_applied = 'yes' and purchase_amount >= (select avg(purchase_amount) from customer);

-- 3. Product Rating Analysis — Ranked the top 5 products by average review rating.
select item_purchased, round(avg(review_rating),2) as avg_rating
from customer
group by item_purchased
order by avg_rating desc
limit 5;

-- 4. Shipping Analysis — Compared average purchase amounts for Standard and Express shipping.
select shipping_type, Round(avg(purchase_amount),2) as avg_purchase_amount
from customer
where shipping_type IN ('standard','Express')
group by shipping_type;

-- 5. Subscription Analysis — Compared customer counts, average spending, and total revenue between subscribers and non-subscribers.

select 
    subscription_status, count(customer_id) as customer_count,
    round(avg(purchase_amount),2) as avg_spending,
    sum(purchase_amount)as total_revenue
    from customer
    group by subscription_status;
    
    -- 6. Discount Dependency Analysis — Identified the top 5 products by percentage of purchases with discounts applied.
    
select
   item_purchased, count(*)as total_orders,sum(case when discount_applied = 'yes' then 1 else 0 end) as discount_orders,
   round((sum(case when discount_applied ='yes' then 1 else 0 end) * 100.0)/ count(*),2) as discount_percentage
   from customer
   group by item_purchased
   order by discount_percentage desc
   limit 5;
   
   -- 7. Customer Segmentation — Classified customers into New, Returning, and Loyal segments based on previous purchases.
   with customer_type as (
   select customer_id,previous_purchases,
                              case
                                  when previous_purchases = 0 then 'new'
                                  when previous_purchases between 1 and 5 then 'Returning'
                                  else 'Loyal'
                                  end as customer_segment
                                  from customer)
				select customer_segment,count(*) AS "Number of Customers" 
from customer_type
group by customer_segment;


-- 8. Product Popularity Analysis — Identified the top 3 most purchased products within each category.
         with RankedProducts as (
		select category, item_purchased,count(*)as total_sold,
        row_number() over (partition by category order by count(*) desc) as rnk
        from customer
        group by category, item_purchased
        )
        select category, item_purchased,total_sold
        from rankedproducts
        where rnk <=3;
        
   -- 9. Repeat Buyer Analysis — Compared subscription status among customers with more than 5 previous purchases.
   
   select subscription_status,count(*) as repeat_customer_count
       from customer
       where previous_purchases >5
       group by subscription_status;
       
     -- 10. Age Group Revenue Analysis — Compared total revenue across customer age groups.
     
	SELECT 
    age_group,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY age_group
ORDER BY total_revenue desc;
                                  
                                  
   


